import {connectClient, drainEngines, startEngineWith, delegatingTo} from '/var/tmp/loop-bench/runs/03a360290795/workspace/target/src/transport/wsTestSupport.js';
import {InMemorySessionStore} from '/var/tmp/loop-bench/runs/03a360290795/workspace/target/src/infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '/var/tmp/loop-bench/runs/03a360290795/workspace/target/src/types/sessionStore.js';

const ROUNDS = Number(process.argv[2] ?? 100);

interface Arrival {
  type: string;
  microtaskBeforeThisRan: boolean;
}

const askOnce = async (url: string, store: SessionStore): Promise<{emptyAtResolve: boolean; order: string[]}> => {
  const client = connectClient(url);
  const frames: string[] = [];
  const arrivals: Arrival[] = [];
  let flag = false;
  let emptyAtResolve = false;
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string};
      if (frame.type === 'connected') {
        client.send(JSON.stringify({type: 'list_sessions'}));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      arrivals.push({type: frame.type, microtaskBeforeThisRan: flag});
      if (frame.type !== 'pong') {
        frames.push(frame.type);
        return;
      }
      queueMicrotask(() => {
        flag = true;
      });
      emptyAtResolve = frames.length === 0;
      resolve();
    });
  });
  // Drain remaining frames so arrivals is complete for the report.
  await new Promise(resolve => setTimeout(resolve, 30));
  client.removeAllListeners('message');
  return {emptyAtResolve, order: arrivals.map(a => `${a.type}${a.microtaskBeforeThisRan ? '(after-microtask)' : ''}`)};
};

let emptyAtResolveCount = 0;
const sampleOrders: string[][] = [];

for (let i = 0; i < ROUNDS; i++) {
  const inner = new InMemorySessionStore();
  const failing: SessionStore = {
    ...delegatingTo(inner),
    listFor: () => Promise.reject(new Error('database offline')),
  };
  const plain = delegatingTo(inner);
  const {url: failingUrl} = await startEngineWith({sessionStore: failing, wsAuth: async () => ({id: 'u1'})});
  const {url: plainUrl} = await startEngineWith({sessionStore: plain, wsAuth: async () => ({id: 'u1'})});

  const failed = await askOnce(failingUrl, failing);
  const unimplemented = await askOnce(plainUrl, plain);

  if (failed.emptyAtResolve) {
    emptyAtResolveCount += 1;
    if (sampleOrders.length < 3) sampleOrders.push(failed.order);
  }
  if (i === 0) {
    console.log('failing order round0:', failed.order.join(' -> '));
    console.log('plain order round0:', unimplemented.order.join(' -> '));
    console.log('plain emptyAtResolve:', unimplemented.emptyAtResolve);
  }
  await drainEngines();
}

console.log(`rounds=${ROUNDS} resolve-saw-empty-frames=${emptyAtResolveCount}`);
if (sampleOrders.length > 0) console.log('sample race orders:', JSON.stringify(sampleOrders));

