export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // Keyed by socket: one connection's answers leave in the order its frames arrived.
  const answers = new WeakMap<WebSocket, Promise<unknown>>();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
      );
    }
    // Each answer joins the connection's tail, so a ping cannot overtake the list sent before it.
    const ahead = answers.get(ws) ?? Promise.resolve();
    const answer = ahead
      .catch(() => undefined)
      .then(() => wsErrorHandler(ws, async () => answerFrame(ws, session, sessionStore, validation)));
    answers.set(ws, answer);
    return answer;
  };
}

